import{_ as s,o as i,c as e,ag as t}from"./chunks/framework.CxkNbRKf.js";const k=JSON.parse('{"title":"Upgrade from 5.4 to 5.5","description":"","frontmatter":{},"headers":[],"relativePath":"installation-guide/upgrade/upgrade-55.md","filePath":"installation-guide/upgrade/upgrade-55.md","lastUpdated":1786379412000}'),n={name:"installation-guide/upgrade/upgrade-55.md"};function l(r,a,o,p,h,d){return i(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="upgrade-from-5-4-to-5-5" tabindex="-1">Upgrade from 5.4 to 5.5 <a class="header-anchor" href="#upgrade-from-5-4-to-5-5" aria-label="Permalink to &quot;Upgrade from 5.4 to 5.5&quot;">​</a></h1><p>This upgrade covers database and configuration changes from NADA <strong>5.4.x</strong> to <strong>5.5</strong>.</p><p>Deploy the NADA <strong>5.5</strong> application files (zip release or Git tag) over your existing install, preserve your <code>application/config</code> customizations (especially <code>database.php</code> and <code>email.php</code>), and clear caches if your environment uses them. Then apply the changes below.</p><h2 id="_1-backup-database" tabindex="-1">1. Backup database <a class="header-anchor" href="#_1-backup-database" aria-label="Permalink to &quot;1. Backup database&quot;">​</a></h2><p>Before you change the database, take a full backup.</p><h2 id="_2-update-database" tabindex="-1">2. Update database <a class="header-anchor" href="#_2-update-database" aria-label="Permalink to &quot;2. Update database&quot;">​</a></h2><p>Use a database client (phpMyAdmin, MySQL Workbench, or the CLI) to run the following on your NADA database.</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ALTER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TABLE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> `users`</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  ADD</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COLUMN </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`forgot_request_ts`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> INT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  ADD</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COLUMN </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`forgot_request_count`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> INT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> DEFAULT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ALTER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TABLE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> `public_requests`</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  ADD</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COLUMN </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`title`</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> VARCHAR</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">500</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">NULL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> AFTER</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> `surveyid`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><h2 id="_3-run-php-migrations" tabindex="-1">3. Run PHP migrations <a class="header-anchor" href="#_3-run-php-migrations" aria-label="Permalink to &quot;3. Run PHP migrations&quot;">​</a></h2><p>After deploying the application files, run the built-in migration runner from the command line:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> index.php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cli/migrate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> latest</span></span></code></pre></div><p>If this command fails or you applied schema changes manually, see <a href="/nada-documentation/installation-guide/database-migrations-cli.html">Database migrations (CLI)</a> for troubleshooting and for marking migrations without re-running SQL.</p><h2 id="what-s-new-in-5-5" tabindex="-1">What&#39;s new in 5.5 <a class="header-anchor" href="#what-s-new-in-5-5" aria-label="Permalink to &quot;What&#39;s new in 5.5&quot;">​</a></h2><ul><li><strong>Driver-based email</strong> — SMTP and SendGrid/API drivers, configurable in <code>application/config/email.php</code></li><li><strong>OAuth/SSO login</strong> — social login support via the new <code>authtype</code> field on users</li><li><strong>Catalog search API</strong> — user-defined filters and DOI search support</li><li><strong>Study IDNO replacement</strong> — IDNO can be replaced via metadata import</li><li><strong>Custom fields on request forms</strong> — administrators can add fields to public data-access request forms</li><li><strong>Tables API</strong> — CSV and JSON export endpoints for tabular data</li><li><strong>CSV export for licensed requests</strong> — download licensed request lists as CSV from the admin interface</li><li><strong>CSRF protection</strong> — site-wide tokens including file-upload endpoints; session regenerated on login</li><li><strong>Forgot-password throttling</strong> — default limit of 3 requests per 5 minutes</li><li><strong>Optional CSP headers</strong> — Content Security Policy support, disabled by default and configurable in site settings</li></ul>',14)])])}const c=s(n,[["render",l]]);export{k as __pageData,c as default};
